        """Every item `get_squad_chat_history` returns, following the `cursor` cursor until the server
        reports no further pages. Starts at `cursor` when one is given.
        """
        guard = _CursorGuard()
        while True:
            page = await self.get_squad_chat_history(squad_id, thread_id=thread_id, include_internal=include_internal, limit=limit, cursor=cursor, request_options=request_options)
